/* Update ammunition pickup physics, collection, animation and scale.
   Animation states share one stack value; index reloads follow calls. */
void devestator_ammo_update(Moby *m) {
    AmmoPickup_6720 *p;
    unsigned int state;
    FxVec position;
    FxVec predicted;
    float value;
    float magnitude;
    float current;
    float target;
    float step;
    float remaining;
    p = (AmmoPickup_6720 *)m->pvars;
    fast_dec_timer(&p->timer);
    state = m->state;
    if (state == 1 || state == 4 || state == 3) {
        magnitude = FastVecLength(&p->velocity);
        if (magnitude != 0.0f) {
            qcopy(&position, &m->pos);
            position.z += 0.5f;
            if (coll_sphere(0.4f, &position, 2, 0)) {
                qcopy(&m->pos, &coll_resolved_pos);
                m->pos.z -= 0.5f;
            }
        }
        p->velocity.z -= g_frame_time_sq * 4.9f;
        FastVecAdd(&predicted, &m->pos, &p->velocity);
        p->velocity.z -= g_frame_time_sq * 4.9f;
        qcopy(&position, &m->pos);
        position.z += 0.1f;
        if (coll_line(&position, &predicted, 2, 0, 0)) {
            clear_u64_value(&p->velocity);
            qcopy(&m->pos, &collision_hit_point);
        } else {
            qcopy(&m->pos, &predicted);
        }
    }
    switch (m->state) {
    case 0:
        m->state = 1;
        break;
    case 1: {
        Hero *player;
        float *value_ptr;
        float height_delta;
        float distance;
        int duration;
        int eligible;
        int idx;
        int sound_idx;
        int account_idx;
        int before;
        int after;
        int difference;
        int sound;
        int elapsed;
        int random;
        int max_ammo;
        value_ptr = &value;
        *value_ptr = (float)m->alpha;
        duration = scale_ticks(30);
        ApproachValue(value_ptr, 128.0f, (float)(128 / duration));
        m->alpha = truncate_float_to_s32(*value_ptr);
        if (p->timer > 0)
            return;
        if (FastVecLength(&p->velocity) != 0.0f)
            return;
        player = (Hero *)(hero_globals_base + 0xE1D);
        eligible = 1;
        height_delta =
            FastAbsF(m->pos.z - player->motion.pos.f[2]);
        if (player->reach_height < height_delta) {
            eligible = 0;
        } else {
            distance = vec_distance_xy(&m->pos, &player->motion.pos);
            if (player->reach_distance < distance)
                eligible = 0;
        }
        idx = p->weapon;
        before = ((int *)(menu_item_enabled_115 + 0x21))[idx];
        max_ammo = ((FxWeaponInfo *)item_price_table)[idx].max;
        if (before >= max_ammo)
            eligible = 0;
        if (m->pos.z < p->resting_height - 2.0f)
            eligible = 1;
        if (((Hero *)(hero_globals_base + 0xE1D))->health.hp == 0)
            eligible = 0;
        if (!eligible)
            goto pickup_failed;

        {
            add_ammo(idx, p->amount);
            sound_idx = p->weapon;
            after = ((int *)(menu_item_enabled_115 + 0x21))[sound_idx];
            if (before < after) {
                difference = after - before;
                if (difference == 1) {
                    sound = ((FxAmmoRecord *)(item_defs_r + sound_idx * sizeof(FxAmmoRecord)))->sound_single;
                } else {
                    sound = ((FxAmmoRecord *)(item_defs_r + sound_idx * sizeof(FxAmmoRecord)))->sound_multiple;
                }
                queue_formatted_dialogue_message(sound, difference, -1);
            }
            account_idx = p->weapon;
            ((int *)(level_render_state_base + 0xA2))[account_idx] += ((int *)(menu_item_enabled_115 + 0x21))[account_idx] - before;
            m->state = 2;
            m->scale *= frame_scale * 0.20000005f + 1.0f;
            clear_u64_value(&p->velocity);
            elapsed = level_frame_counter - ammo_pickup_sound_frame;
            p->rise_speed = g_frame_time * 8.0f;
            random = subtract_integer_with_clamp(elapsed);
            if (scale_ticks(10) < random) {
                Sound_PlayClassSound(0, 0, (int)m, 0xD5);
                ammo_pickup_sound_frame = level_frame_counter;
            }
            return;
        }
    pickup_failed:
        if (m->alpha < 0xFF)
            ++m->alpha;
        if (jet_distance(m, ((Hero *)(hero_globals_base + 0xE1D))->moby) <= -0.2f) {
            m->state = 3;
            p->recovery_timer = scale_ticks(60);
        }
        return;
    }
    case 2: {
        float limit;
        float distance;
        float factor;
        float class_scale;
        ApproachValue(&p->rise_speed, 0.0f, g_frame_time_sq * 24.0f);
        m->pos.z += p->rise_speed;
        limit = FastVecLength(&p->velocity);
        ApproachValue(&limit, g_frame_time * 64.0f, g_frame_time_sq * 24.0f);
        FastVecSub(&p->velocity, hero_globals_base + 0xEED, &m->pos);
        if (m->scale == 0.0f || FastVecLength(&p->velocity) < limit) {
            DeleteMoby(m);
            return;
        }
        vec_scale_to_length(&p->velocity, &p->velocity, limit);
        FastVecAdd(&m->pos, &m->pos, &p->velocity);
        distance = FastVecDist(&m->pos, hero_globals_base + 0xEED);
        factor = (float)scale_ticks(30);
        factor = factor * limit;
        factor = factor + 0.01f;
        distance = distance / factor;
        if (1.0f < distance) {
            distance = 1.0f;
        } else if (distance < 0.3f) {
            distance = 0.3f;
        }
        class_scale = m->pclass->scale;
        ApproachValue(&m->scale, class_scale * distance, class_scale * 0.1f);
        return;
    }
    case 3: {
        float *value_ptr;
        float angle;
        float oscillation;
        float target;
        int phase;
        int random;
        int idx;
        phase = level_frame_counter % 60;
        value = (float)m->alpha;
        angle = (float)phase / 60.0f;
        angle = angle * 6.28318f;
        angle = angle - 3.14159f;
        oscillation = FastCos(angle);
        oscillation = oscillation * 5.0f;
        oscillation = oscillation + 5.0f;
        target = (float)(truncate_float_to_s32(oscillation) + 10);
        value_ptr = &value;
        random = scale_ticks(30);
        ApproachValue(value_ptr, target, (float)(128 / random));
        m->alpha = truncate_float_to_s32(*value_ptr);
        if (jet_distance(m, ((Hero *)g_hero)->moby) >= 0.0f) {
            m->state = 1;
            return;
        }
        idx = p->weapon;
        if (((int *)(menu_item_enabled_115 + 0x21))[idx] <
                ((FxWeaponInfo *)item_price_table)[idx].max) {
            m->state = 1;
        }
        return;
    }
    case 4:
        current = m->scale;
        target = m->pclass->scale;
        step = frame_scale * 0.03f;
        current += (target - current) * step;
        m->scale = current;
        target = m->pclass->scale;
        remaining = (target - current) / target;
        if (remaining < 0.01f) {
            m->scale = target;
            m->state = 1;
            m->collision = m->pclass->collision;
        }
        break;
    }
}
