// Draws a streak of quads along the vector from the moby's joint to its target, swelling in the middle. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/shared/unclassified_002bffa8.c, FUN_L00_002c5dc8.
void draw_swingshot_cable(char *m) {
        char *d;
    Quad quad;
    V4q pos, cur, ja, diff, side, up2, up, t100, t110;
    float len, prog, f25;
    float eps = 0.05f;
    if (m == 0) return;
    d = ((char *)((Moby *)m)->pvars);
    if (d == 0) return;
    quad.q1 = GetEffectTex(0xF);
    quad.c[3] = 0x80808080; quad.c[2] = 0x80808080; quad.c[1] = 0x80808080; quad.c[0] = 0x80808080;
    quad.q2 = 0xFF9000000260L;
    quad.q0 = 5;
    quad.q3 = 0xFF00000044L;
    quad.t[0] = 0; quad.t[1] = 0; quad.t[2] = 1.0f; quad.t[3] = 0;
    quad.t[4] = 0; quad.t[5] = 1.0f; quad.t[6] = 1.0f; quad.t[7] = 1.0f;
    Moby_GetJointWorldPos(m, 0, ja);
    qcopy(pos, *(char **)(d + 0x14) + 0x10);
    qcopy(cur, pos);
    FastVecSub(diff, ja, pos);
    prog = 0.0f;
    len = FastVecLength(diff);
    qcopy(up, diff);
    up[2] = up[2] - 0.1f;
    FastVecCross(side, diff, up);
    FastVecCross(up2, diff, side);
    qcopy(&quad.a[0], pos);
    qcopy(&quad.a[8], pos);
    quad.a[2] = quad.a[2] - eps;
    quad.a[10] = quad.a[10] + eps;
    f25 = FastCos(FastNormalizeAngle(*(float *)(d + 0x18)));
    while (prog < len) {
        float step = 0.2f;
        float rem = len - prog;
        float x, t, a, b;
        if (rem < step) step = rem;
        prog += step;
        x = prog * 3.14159274f;
        a = FastSin(x / len);
        b = FastSin(FastNormalizeAngle(x / *(float *)(d + 0x1C)));
        t = b * a;
        t = t * f25;
        t = t * *(float *)(d + 0x20);
        vec_scale_to_length(diff, diff, step);
        FastVecAdd(cur, cur, diff);
        qcopy(&quad.a[4], cur);
        qcopy(&quad.a[12], cur);
        FastVecSub(t100, g_debug_camera, cur);
        FastVecCross(t110, t100, diff);
        vec_scale_to_length(t110, t110, 0.05f);
        FastVecAdd(&quad.a[4], &quad.a[4], t110);
        FastVecSub(&quad.a[12], &quad.a[12], t110);
        vec_scale_to_length(up, side, t);
        FastVecAdd(&quad.a[4], &quad.a[4], up);
        FastVecAdd(&quad.a[12], &quad.a[12], up);
        draw_world_quad(&quad, 0, 1);
        qcopy(pos, cur);
        qcopy(&quad.a[0], &quad.a[4]);
        qcopy(&quad.a[8], &quad.a[12]);
    }
}
