/* On selected modes, spawn twenty random particles around the moby and set its state to 4. */
void spawn_moby_collision_particles(void *mm) {
    char *m = mm;
    Vec4A v;
    int n, i;
    char *pos;
    switch (CollType()) {
    case 0:
    case 1:
    case 3:
    case 8:
    case 11:
    case 12:
    case 13:
        pos = m + 0x10;
        n = 40;
        i = 19;
        do {
            int a, b, c;
            float f;
            qcopy(&v, pos);
            v.x += random_float_between(-0.3f, 0.3f);
            v.y += random_float_between(-0.3f, 0.3f);
            v.z += random_float_between(-0.3f, 0.3f);
            a = (func_001160D8() + 0x30) & 0x3F;
            b = (func_001160D8() + 0x20) & 0x3F;
            c = func_001160D8() & 0x2F;
            f = random_float_between(100000.0f, 800000.0f);
            PartType05Spawn(&v, a, b, c, f, 0.0f, scale_ticks(func_001160D8() % n + 10));
        } while (--i >= 0);
        m[0x20] = 4;
        break;
    }
}
